<?php
namespace Tests\Feature;use App\Models\{Offer,PriceHistory,Product,Store};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PriceHistoryTest extends TestCase {use RefreshDatabase;public function test_history_is_only_added_when_price_changes():void{$p=Product::create(['brand'=>'ASICS','name'=>'Test','model'=>'TEST','slug'=>'test']);$s=Store::create(['name'=>'S','slug'=>'s','website_url'=>'https://example.com']);$o=Offer::create(['product_id'=>$p->id,'store_id'=>$s->id,'external_id'=>'1','name_original'=>'Test','price'=>299,'currency'=>'BAM','availability'=>'in_stock','product_url'=>'https://example.com','last_checked_at'=>now()]);PriceHistory::create(['offer_id'=>$o->id,'price'=>299,'recorded_at'=>now()]);$this->assertSame(1,$o->priceHistories()->count());if(bccomp((string)$o->price,'279',2)!==0)PriceHistory::create(['offer_id'=>$o->id,'price'=>279,'recorded_at'=>now()]);$this->assertSame(2,$o->priceHistories()->count());}}
